import type { Peer } from "crossws"
import { registerBroadcaster, type EventChange } from "../utils/broadcast"

// Single broadcast channel: every connected peer subscribes to "events" and
// receives all changes. This is the single-user template — there is no
// owner-scoping.
const CHANNEL = "events"

// Track connected peers so the broadcaster can publish to them. A broadcast
// originating from an HTTP handler (no peer context) reaches peers via this
// registry.
const peers = new Set<Peer>()

// Register how broadcastEventChange (called by the API after a successful write)
// reaches connected clients. Publishes every change to all peers.
registerBroadcaster((change: EventChange) => {
  const payload = JSON.stringify(change)
  for (const peer of peers) {
    try {
      peer.send(payload)
    } catch {
      // Drop unreachable peers silently.
    }
  }
})

export default defineWebSocketHandler({
  async open(peer) {
    // TODO(auth): authenticate the peer in open() and subscribe it to a per-user topic; scope broadcasts to the owner.
    peers.add(peer)
    peer.subscribe(CHANNEL)
  },

  message(peer, message) {
    // Client → server messages are only used for a lightweight ping/keepalive.
    if (message.text() === "ping") peer.send("pong")
  },

  close(peer) {
    peers.delete(peer)
  },

  error(peer) {
    peers.delete(peer)
  },
})

import type { EventDTO } from "./eventMapper"

export type EventChange =
  | { type: "created"; event: EventDTO }
  | { type: "updated"; event: EventDTO }
  | { type: "deleted"; id: string; ownerId: string | null }

// Publishes an event change to connected WebSocket peers. The actual crossws
// publish is wired in the WebSocket handler (section 8); this indirection keeps
// the API handlers decoupled from the transport and lets them broadcast only
// AFTER a successful write. No-op until a publisher registers.
let publisher: ((change: EventChange) => void) | null = null

export function registerBroadcaster(fn: (change: EventChange) => void): void {
  publisher = fn
}

export async function broadcastEventChange(change: EventChange): Promise<void> {
  try {
    publisher?.(change)
  } catch {
    // Broadcasting must never break the API response.
  }
}

import { ref, onScopeDispose } from "vue"

// Wire-format event: dates are ISO strings over the socket.
interface EventDTO {
  id: string
  ownerId?: string | null
  title: string
  startDate: string
  endDate: string
  [key: string]: unknown
}

// A change broadcast over the WebSocket. Matches the server's EventChange.
export type RemoteEventChange =
  | { type: "created"; event: EventDTO }
  | { type: "updated"; event: EventDTO }
  | { type: "deleted"; id: string; ownerId?: string | null }

// Connects to the Nitro WebSocket and applies remote event changes. Real-time is
// an enhancement: if the socket is unavailable, CRUD over HTTP still works. The
// caller supplies `apply` (useCalendarData.applyRemote) and a set of ids the
// client itself just wrote, so echoes of its own changes aren't re-applied.
export function useCalendarRealtime(
  apply: (change: RemoteEventChange) => void,
  isOwnEcho: (change: RemoteEventChange) => boolean,
  onReconnect?: () => void,
) {
  const connected = ref(false)
  let ws: WebSocket | null = null
  let reconnectTimer: ReturnType<typeof setTimeout> | null = null
  let stopped = false
  let hadConnected = false

  const url = () => {
    const proto = location.protocol === "https:" ? "wss:" : "ws:"
    return `${proto}//${location.host}/_ws`
  }

  const connect = () => {
    if (stopped || !import.meta.client) return
    try {
      ws = new WebSocket(url())
    } catch {
      scheduleReconnect()
      return
    }

    ws.onopen = () => {
      connected.value = true
      // On a RE-connect (not the first connect), resync so changes missed during
      // the outage are picked up.
      if (hadConnected) onReconnect?.()
      hadConnected = true
    }

    ws.onmessage = (ev) => {
      try {
        if (ev.data === "pong") return
        const change = JSON.parse(ev.data) as RemoteEventChange
        if (isOwnEcho(change)) return
        apply(change)
      } catch {
        // Ignore malformed frames.
      }
    }

    ws.onclose = () => {
      connected.value = false
      scheduleReconnect()
    }

    ws.onerror = () => {
      ws?.close()
    }
  }

  const scheduleReconnect = () => {
    if (stopped || reconnectTimer) return
    reconnectTimer = setTimeout(() => {
      reconnectTimer = null
      connect()
    }, 3000)
  }

  const start = () => {
    stopped = false
    connect()
  }

  const stop = () => {
    stopped = true
    if (reconnectTimer) {
      clearTimeout(reconnectTimer)
      reconnectTimer = null
    }
    ws?.close()
    ws = null
    connected.value = false
  }

  onScopeDispose(stop)

  return { connected, start, stop }
}
